// pre-order into a Span<byte>: flag 1 and 4 bytes of value, flag 0 means null
static void Write(TreeNode node, Span<byte> buf, ref int pos) {
    if (node == null) { buf[pos++] = 0; return; }
    buf[pos++] = 1;
    BinaryPrimitives.WriteInt32LittleEndian(buf.Slice(pos), node.val);
    pos += 4;
    Write(node.left, buf, ref pos);
    Write(node.right, buf, ref pos);
}
// the size is known up front: 5 bytes per node and 1 for each of the n + 1 nulls — 6n + 1

